begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select api.portal_room_snapshot('duindorp-halloween-2026','12000000-0000-0000-0000-000000000001') is not null;
select set_config('test.team_channel',(select id::text from app_private.portal_room_channels where portal_id='12000000-0000-0000-0000-000000000001'),true);
select set_config('test.community',(select id::text from app_private.portal_room_channels where kind='community' and name='Algemeen' limit 1),true);
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','invite','{"email":"parent-size-5@example.invalid","firstName":"Vijf","lastName":"Test","role":"viewer"}',gen_random_uuid())$$,'new invitation for boundary checks');
select set_config('test.invite',(select id::text from app_private.portal_team_invites where email='parent-size-5@example.invalid'),true);
select set_config('test.token',app_private.poortkamer_invite_token(current_setting('test.invite')::uuid),true);
select ok(api.portal_invitation_check(current_setting('test.token'),' PARENT-SIZE-5@EXAMPLE.INVALID '),'invitation email normalized');
select ok(not api.portal_invitation_check(current_setting('test.token'),'another@example.invalid'),'preflight never accepts another email');
update auth.users set email_confirmed_at=null where id='a0000000-0000-0000-0000-000000000005';
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
select throws_ok($$select api.portal_invitation_accept(current_setting('test.token'))$$,'42501','INVITATION_UNAVAILABLE','unverified account cannot accept');
update auth.users set email_confirmed_at=now() where id='a0000000-0000-0000-0000-000000000005';
update app_private.portal_team_invites set expires_at=now()-interval '1 second' where id=current_setting('test.invite')::uuid;
select throws_ok($$select api.portal_invitation_accept(current_setting('test.token'))$$,'42501','INVITATION_UNAVAILABLE','expired key cannot accept');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','resend',jsonb_build_object('inviteId',current_setting('test.invite')),gen_random_uuid())$$,'resend expires the old key');
select ok(not api.portal_invitation_check(current_setting('test.token'),'parent-size-5@example.invalid'),'old key is invalid after resend');
select is((select count(*)::integer from app_private.portal_team_invites where email='parent-size-5@example.invalid' and revoked_at is null),1,'one pending invitation per email');
select set_config('test.new_invite',(select id::text from app_private.portal_team_invites where email='parent-size-5@example.invalid' and revoked_at is null),true);
select api.portal_team_command('12000000-0000-0000-0000-000000000001','revoke_invite',jsonb_build_object('inviteId',current_setting('test.new_invite')),gen_random_uuid());
select is(api.portal_invitation_mail_payload(current_setting('test.new_invite')::uuid),null::jsonb,'revoked invitation is suppressed at delivery time');
select throws_ok($$select api.portal_team_command('12000000-0000-0000-0000-000000000001','revoke','{"userId":"e0000000-0000-0000-0000-000000000001"}',gen_random_uuid())$$,'P0001','TRANSFER_OWNER_FIRST','cannot revoke sole primary');
select throws_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','status','{"state":"open"}',gen_random_uuid())$$,'40001','STALE_VERSION','missing status version rejected');
select throws_ok($$select api.portal_chat_send(current_setting('test.team_channel')::uuid,repeat('a',1001),gen_random_uuid(),'12000000-0000-0000-0000-000000000001')$$,'P0001','INVALID_MESSAGE','1000 character server limit');
select throws_ok($$select api.portal_chat_send(current_setting('test.team_channel')::uuid,'Wrong resource',gen_random_uuid(),'12000000-0000-0000-0000-000000000002')$$,'42501','NOT_AUTHORIZED','team channel cannot impersonate another portal');
insert into app_private.portal_owners(portal_id,user_id,role,first_name,last_name) values('12000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001','viewer','Voornaam','AlleenIntern');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.message',(api.portal_chat_send(current_setting('test.community')::uuid,'Een bericht op het plein',gen_random_uuid(),'12000000-0000-0000-0000-000000000001')->>'id'),true);
select is((api.portal_chat_snapshot(current_setting('test.community')::uuid)->'messages'->0->>'mentionUserId'),'a0000000-0000-0000-0000-000000000001','community mention target is an active author identifier');
select ok(api.portal_chat_snapshot(current_setting('test.community')::uuid)::text not like '%AlleenIntern%','community mention projection never adds surname');
select set_config('test.mention_message',(api.portal_chat_send(current_setting('test.community')::uuid,'Een vermelding voor onze poortwachter',gen_random_uuid(),'12000000-0000-0000-0000-000000000001',array['e0000000-0000-0000-0000-000000000001']::uuid[])->>'id'),true);
select is((select count(*)::integer from app_private.portal_push_outbox where kind='mention' and dedupe_key='mention:'||current_setting('test.mention_message') and user_id='e0000000-0000-0000-0000-000000000001'),1,'community mention queues one notification for active recipient');
select throws_ok($$select api.portal_chat_send(current_setting('test.community')::uuid,'Geen niet-leden',gen_random_uuid(),'12000000-0000-0000-0000-000000000001',array['a0000000-0000-0000-0000-000000000005']::uuid[])$$,'P0001','INVALID_MENTION','community cannot notify a non-member');
insert into app_private.portal_room_reads(channel_id,user_id,muted) values(current_setting('test.community')::uuid,'e0000000-0000-0000-0000-000000000001',true);
select set_config('test.muted_mention',(api.portal_chat_send(current_setting('test.community')::uuid,'Gedempt kanaal respecteren',gen_random_uuid(),'12000000-0000-0000-0000-000000000001',array['e0000000-0000-0000-0000-000000000001']::uuid[])->>'id'),true);
select is((select count(*)::integer from app_private.portal_push_outbox where dedupe_key='mention:'||current_setting('test.muted_mention')),0,'community mention respects channel mute');
select lives_ok($$select api.portal_chat_action(current_setting('test.community')::uuid,'read',jsonb_build_object('messageId',current_setting('test.message')))$$,'read marker stored');
select lives_ok($$select api.portal_chat_action(current_setting('test.community')::uuid,'report',jsonb_build_object('messageId',current_setting('test.message'),'reason','Graag even beoordelen'))$$,'member can report');
select lives_ok($$select api.portal_chat_action(current_setting('test.community')::uuid,'report',jsonb_build_object('messageId',current_setting('test.message'),'reason','Graag even beoordelen'))$$,'report retry is idempotent');
select is((select count(*)::integer from app_private.portal_room_reports where message_id=current_setting('test.message')::bigint),1,'one report per member and message');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_chat_action(current_setting('test.community')::uuid,'mute_author',jsonb_build_object('messageId',current_setting('test.message'),'reason','Tijdelijke rust op het plein'))$$,'organization can mute community author');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select api.portal_chat_send(current_setting('test.community')::uuid,'Niet toegestaan',gen_random_uuid(),'12000000-0000-0000-0000-000000000001')$$,'42501','COMMUNITY_MUTED','community mute enforced');
select lives_ok($$select api.portal_chat_send(current_setting('test.team_channel')::uuid,'Team blijft bereikbaar',gen_random_uuid(),'12000000-0000-0000-0000-000000000001')$$,'community mute preserves own team chat');
select api.portal_notification_preferences_set('{"mention":false}');
select api.push_subscription_upsert('https://push.example.invalid/room-boundary-device',repeat('p',32),repeat('a',16),'local test','test');
select app_private.poortkamer_push('12000000-0000-0000-0000-000000000001','mention','boundary-mention','a0000000-0000-0000-0000-000000000001');
select set_config('test.notification',(select id::text from app_private.portal_push_outbox where dedupe_key='boundary-mention'),true);
select is((select jsonb_array_length(x->'targets') from jsonb_array_elements(api.worker_claim_portal_push()) x where x->>'id'=current_setting('test.notification')),0,'disabled category excluded at delivery');
select ok(not has_function_privilege('authenticated','api.worker_record_portal_push(uuid,uuid[],boolean)','execute'),'clients cannot forge successful push delivery');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','help','{"shareCommunity":true}',gen_random_uuid())$$,'explicit stock help share');
select ok((select stock_help_requested_at is not null from app_private.portals where id='12000000-0000-0000-0000-000000000001'),'help request remains visible to organizer');
select throws_ok($$select api.portal_room_update('12000000-0000-0000-0000-000000000001','help','{"shareCommunity":false}',gen_random_uuid())$$,'P0001','EXPLICIT_CONFIRMATION_REQUIRED','no community publication without confirmation');
select lives_ok($$do $test$ begin for i in 1..15 loop perform api.portal_chat_send(current_setting('test.team_channel')::uuid,'Budgettest '||i,gen_random_uuid(),'12000000-0000-0000-0000-000000000001'); end loop; end $test$;$$,'bounded burst accepted');
select throws_ok($$select api.portal_chat_send(current_setting('test.team_channel')::uuid,'Te snel',gen_random_uuid(),'12000000-0000-0000-0000-000000000001')$$,'P0001','RATE_LIMITED','server limits successful chat burst');
select * from finish();
rollback;
